css:
/* Base Styles */
body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  background-color: #f8f9fa;
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
}

/* Container */
.getaround-container {
  position: relative;
  display: inline-block;
}

/* Main Button */
.getaround-button {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 14px 28px;
  background: linear-gradient(135deg, #4a6bff, #6a11cb);
  color: white;
  border-radius: 50px;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
  box-shadow: 0 8px 15px rgba(0, 0, 0, 0.1);
  position: relative;
  overflow: hidden;
  z-index: 10;
}

.getaround-button::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    135deg,
    rgba(106, 17, 203, 0.4),
    rgba(74, 107, 255, 0.4)
  );
  filter: blur(15px);
  opacity: 0;
  transition: opacity 0.5s ease;
  z-index: -1;
}

.getaround-button::after {
  content: "";
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.3) 0%,
    rgba(255, 255, 255, 0) 70%
  );
  transform: scale(0);
  transition: transform 0.6s ease-out;
  z-index: -1;
}

.getaround-button:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.2);
}

.getaround-button:hover::before {
  opacity: 1;
}

.getaround-button:hover::after {
  transform: scale(1);
}

.getaround-button:active {
  transform: translateY(-2px);
  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.15);
}

/* Button Text */
.getaround-text {
  font-size: 18px;
  font-weight: 600;
  margin-right: 12px;
  transition: letter-spacing 0.3s ease;
}

.getaround-button:hover .getaround-text {
  letter-spacing: 1px;
}

/* Button Icon */
.getaround-icon {
  width: 24px;
  height: 24px;
  fill: white;
  transition: transform 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.getaround-button:hover .getaround-icon {
  transform: rotate(360deg);
}

/* Tooltip */
.getaround-tooltip {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) scale(0.9);
  background: rgba(255, 255, 255, 0.95);
  border-radius: 16px;
  padding: 16px;
  box-shadow: 0 15px 30px rgba(0, 0, 0, 0.15);
  opacity: 0;
  visibility: hidden;
  transition: all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  z-index: 100;
  margin-top: 12px;
  backdrop-filter: blur(10px);
}

.getaround-container:hover .getaround-tooltip {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) scale(1);
}

.getaround-tooltip::before {
  content: "";
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  border-width: 0 10px 10px 10px;
  border-style: solid;
  border-color: transparent transparent rgba(255, 255, 255, 0.95) transparent;
}

/* Icons Container */
.getaround-icons {
  display: flex;
  gap: 16px;
}

/* Icon Buttons */
.getaround-icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #f1f3f5;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

.getaround-icon-btn svg {
  width: 24px;
  height: 24px;
  transition: all 0.3s ease;
}

.getaround-icon-btn:hover {
  transform: translateY(-5px) scale(1.1);
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.15);
}

.getaround-icon-btn:active {
  transform: translateY(-2px) scale(1.05);
}

/* Python Icon */
.getaround-icon-btn.python:hover {
  background: linear-gradient(135deg, #3776ab, #ffd343);
}

.getaround-icon-btn.python:hover svg {
  fill: white;
}

/* Chat Icon */
.getaround-icon-btn.chat:hover {
  background: linear-gradient(135deg, #25d366, #128c7e);
}

.getaround-icon-btn.chat:hover svg {
  fill: white;
}

/* Like Icon */
.getaround-icon-btn.like:hover {
  background: linear-gradient(135deg, #ff4d4d, #d32f2f);
}

.getaround-icon-btn.like:hover svg {
  fill: white;
}

/* Pulse Animation */
@keyframes getaround-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(74, 107, 255, 0.4);
  }
  70% {
    box-shadow: 0 0 0 15px rgba(74, 107, 255, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(74, 107, 255, 0);
  }
}

.getaround-button {
  animation: getaround-pulse 3s infinite;
}

/* Responsive Design */
@media (max-width: 768px) {
  .getaround-button {
    padding: 12px 24px;
  }

  .getaround-text {
    font-size: 16px;
  }

  .getaround-tooltip {
    padding: 12px;
  }

  .getaround-icons {
    gap: 12px;
  }

  .getaround-icon-btn {
    width: 44px;
    height: 44px;
  }

  .getaround-icon-btn svg {
    width: 20px;
    height: 20px;
  }
}
